package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import javax.xml.namespace.QName;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NullPropertyPointer;
import org.apache.commons.jxpath.ri.model.beans.PropertyOwnerPointer;
import org.apache.commons.jxpath.ri.model.beans.PropertyPointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class NullPropertyPointer_createPath_TriageGen1Test {

    private JXPathContext mockContext;
    private NodePointer mockParent;
    private QName mockQName;

    @Before
    public void setUp() {
        mockContext = mock(JXPathContext.class);
        mockParent = mock(NodePointer.class);
        mockQName = new QName("testName");
    }

    /**
     * Tests the branch where isAttribute() is true.
     */
    @Test
    public void testCreatePath_IsAttribute() {
        // Arrange
        NullPropertyPointer pointer = mock(NullPropertyPointer.class);
        when(pointer.isAttribute()).thenReturn(true);
        when(pointer.getName()).thenReturn(mockQName);

        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttributePointer = mock(NodePointer.class);

        // We need to use a real instance or a spy to trigger the logic, 
        // but since we are testing the method inside NullPropertyPointer, 
        // we use a spy to control isAttribute() and getName()
        NullPropertyPointer spyPointer = org.mockito.Mockito.spy(new NullPropertyPointer(mockParent));

        when(spyPointer.isAttribute()).thenReturn(true);
        when(spyPointer.getName()).thenReturn(mockQName);
        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(mockContext, mockQName)).thenReturn(mockAttributePointer);

        Object testValue = "attributeValue";

        // Act
        NodePointer result = spyPointer.createPath(mockContext, testValue);

        // Assert
        assertNotNull(result);
        assertEquals(mockAttributePointer, result);
        verify(mockAttributePointer).setValue(testValue);
    }

    /**
     * Tests the branch where isAttribute() is false AND newParent is NOT a PropertyOwnerPointer.
     */
    @Test
    public void testCreatePath_NotAttribute_NotPropertyOwnerPointer() {
        // Arrange
        NullPropertyPointer spyPointer = org.mockito.Mockito.spy(new NullPropertyPointer(mockParent));

        when(spyPointer.isAttribute()).thenReturn(false);
        when(spyPointer.getName()).thenReturn(mockQName);

        NodePointer mockNewParent = mock(NodePointer.class);
        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);

        // We need to ensure mockNewParent is NOT an instance of PropertyOwnerPointer
        // In Mockito, a mock of NodePointer is not a PropertyOwnerPointer unless specified

        Object testValue = "childValue";
        NodePointer mockChildPointer = mock(NodePointer.class);
        when(mockNewParent.createChild(eq(mockContext), eq(mockQName), any(int.class), eq(testValue)))
            .thenReturn(mockChildPointer);

        // Act
        NodePointer result = spyPointer.createPath(mockContext, testValue);

        // Assert
        assertNotNull(result);
        assertEquals(mockChildPointer, result);
    }

    /**
     * Tests the branch where isAttribute() is false AND newParent IS a PropertyOwnerPointer.
     */
    @Test
    public void testCreatePath_NotAttribute_IsPropertyOwnerPointer() {
        // Arrange
        NullPropertyPointer spyPointer = org.mockito.Mockito.spy(new NullPropertyPointer(mockParent));

        when(spyPointer.isAttribute()).thenReturn(false);
        when(spyPointer.getName()).thenReturn(mockQName);

        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropertyPointer = mock(NodePointer.class);

        when(mockParent.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropertyPointer);

        Object testValue = "propertyValue";
        NodePointer mockChildPointer = mock(NodePointer.class);
        when(mockPropertyPointer.createChild(eq(mockContext), eq(mockQName), any(int.class), eq(testValue)))
            .thenReturn(mockChildPointer);

        // Act
        NodePointer result = spyPointer.createPath(mockContext, testValue);

        // Assert
        assertNotNull(result);
        assertEquals(mockChildPointer, result);
        verify(mockPop).getPropertyPointer();
    }
}
